+const CUE: Record<
+	Facts["status"],
+	{ text: string; tone: ComposerSuggestionItem["tone"] }
+> = {
+	completed: { text: "after the last turn", tone: "neutral" },
+	cancelled: { text: "after the turn you stopped", tone: "neutral" },
+	failed: { text: "after the turn that failed", tone: "repair" },
