+	const publish = (next?: Facts) => {
+		revision += 1;
+		if (next) {
+			facts = next;
+			cursor = 0;
+			turn = `r${revision}`;
+			skipped = new Set();
+		}
+		ui?.update("composer.suggestions", shown());
+	};
+
+	const offers = (itemId: string) =>
+		shown()?.items.some((item) => item.id === itemId) ?? false;
+
